import re

def check_password_strength(password):
    requirements = {
        'min_length': 12,
        'uppercase': re.compile(r'[A-Z]'),
        'lowercase': re.compile(r'[a-z]'),
        'digit': re.compile(r'[0-9]'),
        'special_char': re.compile(r'[!@#$%^&*(),.?":{}|<>]')
    }

    issues = []

    if len(password) < requirements['min_length']:
        issues.append('Password must be at least 12 characters long.')

    if not requirements['uppercase'].search(password):
        issues.append('Password must contain at least one uppercase letter.')

    if not requirements['lowercase'].search(password):
        issues.append('Password must contain at least one lowercase letter.')

    if not requirements['digit'].search(password):
        issues.append('Password must contain at least one digit.')

    if not requirements['special_char'].search(password):
        issues.append('Password must contain at least one special character.')

    if issues:
        print('Password does not meet the following requirements:')
        for issue in issues:
            print(f'- {issue}')
    else:
        print('Password meets all requirements.')

# Example usage
password = input('Enter your password: ')
check_password_strength(password)
